use vstd::prelude::*;

verus! {

/// Specification: inserting `delimiter` between consecutive elements of `numbers`.
spec fn intersperse_spec(s: Seq<i8>, delimiter: i8) -> Seq<i8>
    decreases s.len()
{
    if s.len() <= 1 {
        s
    } else {
        // For s = [a0, a1, a2, ...], produce [a0, d, a1, d, a2, ...]
        seq![s[0], delimiter] + intersperse_spec(s.subrange(1, s.len()), delimiter)
    }
}

fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> (result: Vec<i8>)
    ensures
        result@ == intersperse_spec(numbers@, delimiter),
{
    let n = numbers.len();

    // Length 0 or 1: unchanged
    if n <= 1 {
        return numbers;
    }

    let mut out: Vec<i8> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            i <= n,
            // out is exactly the interspersed sequence of the prefix numbers[0..i)
            out@ == intersperse_spec(numbers@.subrange(0, i as int), delimiter),
        decreases n - i,
    {
        // Push numbers[i]
        out.push(numbers[i]);

        // Update i (we have now consumed numbers[i])
        i = i + 1;

        // If not at the end, insert delimiter
        if i < n {
            out.push(delimiter);
        }
    }

    // At loop end, i == n, so out equals spec for the entire array.
    out
}

} // verus!

